/**
 * Auto-generated from res/values/colors.xml and res/values-night/colors.xml.
 * Keep in sync manually if the XML palettes change until those XML files are removed
 * at the end of the migration (Fase 6). Includes the Fixed color roles since the
 * no-Fixed-roles ColorScheme constructor is deprecated as of Compose BOM 2026.06.00.
 */
enum class MikuPaletteKey(val prefKey: String) {
    Red("1"),
    Pink("2"),
    Purple("3"),
    DeepPurple("4"),
    Indigo("5"),
    Blue("6"),
    Cyan("7"),
    Teal("8"),
    Green("9"),
    LightGreen("10"),
    Lime("11"),
    Yellow("12"),
    Amber("13"),
    Orange("14"),
    Brown("15"),
    BlueGrey("16"),
}

fun mikuColorScheme(paletteKey: String, darkTheme: Boolean): ColorScheme {
    return when (paletteKey) {
        "1" -> if (darkTheme) MikuScheme_RedDark else MikuScheme_RedLight
        "2" -> if (darkTheme) MikuScheme_PinkDark else MikuScheme_PinkLight
        "3" -> if (darkTheme) MikuScheme_PurpleDark else MikuScheme_PurpleLight
        "4" -> if (darkTheme) MikuScheme_DeepPurpleDark else MikuScheme_DeepPurpleLight
        "5" -> if (darkTheme) MikuScheme_IndigoDark else MikuScheme_IndigoLight
        "6" -> if (darkTheme) MikuScheme_BlueDark else MikuScheme_BlueLight
        "7" -> if (darkTheme) MikuScheme_CyanDark else MikuScheme_CyanLight
        "8" -> if (darkTheme) MikuScheme_TealDark else MikuScheme_TealLight
        "9" -> if (darkTheme) MikuScheme_GreenDark else MikuScheme_GreenLight
        "10" -> if (darkTheme) MikuScheme_LightGreenDark else MikuScheme_LightGreenLight
        "11" -> if (darkTheme) MikuScheme_LimeDark else MikuScheme_LimeLight
        "12" -> if (darkTheme) MikuScheme_YellowDark else MikuScheme_YellowLight
        "13" -> if (darkTheme) MikuScheme_AmberDark else MikuScheme_AmberLight
        "14" -> if (darkTheme) MikuScheme_OrangeDark else MikuScheme_OrangeLight
        "15" -> if (darkTheme) MikuScheme_BrownDark else MikuScheme_BrownLight
        "16" -> if (darkTheme) MikuScheme_BlueGreyDark else MikuScheme_BlueGreyLight
        else -> if (darkTheme) MikuScheme_TealDark else MikuScheme_TealLight // fallback matches ThemeManager default "8"
    }
}

